#include "DB2Store.h"
#include "DB2Structure.h"
#include "DB2LoadInfo.h"
#include <iostream>
int main(int argc,char** argv){if(argc!=2)return 1;
 DB2Storage<ItemEntry> base("Item.db2",ItemLoadInfo::Instance());DB2Storage<ItemSparseEntry> items("ItemSparse.db2",ItemSparseLoadInfo::Instance());DB2Storage<ItemEffectEntry> uses("ItemEffect.db2",ItemEffectLoadInfo::Instance());DB2Storage<QuestPackageItemEntry> rewards("QuestPackageItem.db2",QuestPackageItemLoadInfo::Instance());DB2Storage<CreatureDisplayInfoEntry> displays("CreatureDisplayInfo.db2",CreatureDisplayInfoLoadInfo::Instance());DB2Storage<CreatureModelDataEntry> models("CreatureModelData.db2",CreatureModelDataLoadInfo::Instance());DB2Storage<SpellEntry> spells("Spell.db2",SpellLoadInfo::Instance());DB2Storage<SpellEffectEntry> effects("SpellEffect.db2",SpellEffectLoadInfo::Instance());DB2Storage<FactionTemplateEntry> factions("FactionTemplate.db2",FactionTemplateLoadInfo::Instance());
 if(!base.Load(argv[1],0)||!items.Load(argv[1],0)||!uses.Load(argv[1],0)||!rewards.Load(argv[1],0)||!displays.Load(argv[1],0)||!models.Load(argv[1],0)||!spells.Load(argv[1],0)||!effects.Load(argv[1],0)||!factions.Load(argv[1],0))return 2;
 auto baseItem=base.LookupEntry(138021);auto item=items.LookupEntry(138021);if(!baseItem||!item||item->MaxCount||item->Stackable!=10||item->Bonding!=4||item->StartQuestID||item->Flags[0]!=67584||item->Flags[1]!=8192)return 3;std::cout<<"item138021 class="<<unsigned(baseItem->ClassID)<<" "<<item->Display->Str[0]<<" max="<<item->MaxCount<<" stack="<<item->Stackable<<" bonding="<<unsigned(item->Bonding)<<" flags="<<item->Flags[0]<<","<<item->Flags[1]<<'\n';unsigned casts=0;for(auto u:uses)if(u->ItemID==138021)++casts;if(casts)return 3;std::cout<<"item138021 use="<<casts<<'\n';
 for(auto pkg:{17907,17909}){unsigned count=0;for(auto r:rewards)if(r->PackageID==pkg){if(!items.LookupEntry(r->ItemID)||r->ItemQuantity!=1)return 4;++count;std::cout<<"package"<<pkg<<" item="<<r->ItemID<<" quantity="<<r->ItemQuantity<<" display="<<unsigned(r->DisplayType)<<'\n';}if(count!=2)return 4;std::cout<<"package"<<pkg<<" count="<<count<<'\n';}
 for(auto id:{70178,70587,68749,65137,70227}){auto d=displays.LookupEntry(id);if(!d)return 5;auto m=models.LookupEntry(d->ModelID);if(!m||!m->FileDataID)return 5;std::cout<<"display"<<id<<" model="<<m->ID<<" file="<<m->FileDataID<<'\n';}
 for(auto id:{145953,29266,213961,123169}){auto s=spells.LookupEntry(id);if(!s)return 6;std::cout<<"spell"<<id<<" "<<s->Name->Str[0]<<'\n';bool feign=false,dummy=false;for(auto e:effects)if(e->SpellID==id){feign|=e->EffectAura==12;dummy|=e->EffectAura==4;std::cout<<"effect"<<id<<" index="<<e->EffectIndex<<" type="<<e->Effect<<" aura="<<e->EffectAura<<'\n';}if(feign!=(id==29266)||(id!=123169&&!dummy))return 9;}
 for(auto id:{2030,7,2785,190}){auto f=factions.LookupEntry(id);if(!f)return 7;if((id==2785||id==190)&&(f->IsHostileTo(*factions.LookupEntry(1))||f->IsHostileTo(*factions.LookupEntry(2))))return 8;std::cout<<"faction"<<id<<" id="<<f->Faction<<" group="<<unsigned(f->FactionGroup)<<" friends="<<unsigned(f->FriendGroup)<<" enemies="<<unsigned(f->EnemyGroup)<<'\n';}
}
